CREATE TABLE advice_sheet (id TEXT PRIMARY KEY, title TEXT NOT NULL, body_md TEXT NOT NULL, audience TEXT NOT NULL CHECK (audience IN ('adults','minors','all')), visible_modes TEXT NOT NULL CHECK (json_valid(visible_modes)), tags TEXT NOT NULL CHECK (json_valid(tags)), sources TEXT NOT NULL CHECK (json_valid(sources)), status TEXT NOT NULL CHECK (status IN ('draft','reviewed','published','retired')), version INTEGER NOT NULL DEFAULT 1, draft_origin TEXT NOT NULL CHECK (draft_origin IN ('ai','human')), reviewed_by TEXT REFERENCES user(id) ON DELETE SET NULL, reviewed_at TEXT, published_at TEXT, retired_at TEXT, updated_at TEXT NOT NULL, content_hash TEXT NOT NULL) STRICT;
CREATE TABLE applied_op (op_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, entity TEXT NOT NULL, row_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('applied','applied_partial','duplicate','rejected')), assigned_rev INTEGER, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE coach_call (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, thread_id TEXT, day TEXT NOT NULL, created_at TEXT NOT NULL, requested_model TEXT NOT NULL, effective_model TEXT, fallback_used INTEGER NOT NULL DEFAULT 0 CHECK (fallback_used IN (0,1)), api_calls INTEGER NOT NULL DEFAULT 0 CHECK (api_calls >= 0), input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0), cache_write_tokens INTEGER NOT NULL DEFAULT 0 CHECK (cache_write_tokens >= 0), cache_read_tokens INTEGER NOT NULL DEFAULT 0 CHECK (cache_read_tokens >= 0), output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0), cost_usd_micros INTEGER NOT NULL DEFAULT 0 CHECK (cost_usd_micros >= 0), first_text_latency_ms INTEGER, duration_ms INTEGER NOT NULL DEFAULT 0 CHECK (duration_ms >= 0), stop_reason TEXT, refusal_category TEXT, tool_rounds INTEGER NOT NULL DEFAULT 0 CHECK (tool_rounds >= 0), filter_blocks INTEGER NOT NULL DEFAULT 0 CHECK (filter_blocks >= 0), thinking_dropped INTEGER NOT NULL DEFAULT 0 CHECK (thinking_dropped >= 0), error_code TEXT, counted INTEGER NOT NULL DEFAULT 0 CHECK (counted IN (0,1))) STRICT;
CREATE TABLE coach_message (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES coach_thread(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, seq INTEGER NOT NULL, role TEXT NOT NULL CHECK (role IN ('user','assistant','system')), blocks TEXT CHECK (json_valid(blocks)), display_text TEXT, display_extras TEXT CHECK (json_valid(display_extras)), client_message_id TEXT, ai_generated INTEGER NOT NULL DEFAULT 0 CHECK (ai_generated IN (0,1)), effective_model TEXT, stop_reason TEXT, truncated INTEGER NOT NULL DEFAULT 0 CHECK (truncated IN (0,1)), created_at TEXT NOT NULL, UNIQUE (thread_id, seq), UNIQUE (thread_id, client_message_id)) STRICT;
CREATE TABLE coach_report (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, thread_id TEXT, message_seq INTEGER NOT NULL, category TEXT NOT NULL CHECK (category IN ('inaccurate','unsafe','inappropriate','other')), comment TEXT CHECK (length(comment) <= 500), exchange_text TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE coach_safety_counter (month TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('help_emergency','help_pain','help_eating_disorder','help_doping','help_pregnancy','help_distress','filter_block','refusal')), count INTEGER NOT NULL DEFAULT 0 CHECK (count >= 0), PRIMARY KEY (month, kind)) STRICT;
CREATE TABLE coach_state (id INTEGER PRIMARY KEY CHECK (id = 1), enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0,1)), suspended_until TEXT, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE coach_thread (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, day TEXT NOT NULL, audience TEXT NOT NULL CHECK (audience IN ('adult','minor')), persona TEXT NOT NULL CHECK (persona IN ('ombre','skald','scribe')), model TEXT NOT NULL, effort TEXT NOT NULL CHECK (effort IN ('low','medium','high')), prompt_version TEXT NOT NULL, tools_version TEXT NOT NULL, brief_schema TEXT NOT NULL, brief TEXT CHECK (json_valid(brief)), slot_aliases TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(slot_aliases)), is_open INTEGER NOT NULL DEFAULT 1 CHECK (is_open IN (0,1)), closed_reason TEXT CHECK (closed_reason IN ('version_change','health_withdrawn','day_over','persona_change','nutrition_mode_change')), user_message_count INTEGER NOT NULL DEFAULT 0 CHECK (user_message_count >= 0), created_at TEXT NOT NULL, last_message_at TEXT) STRICT;
CREATE TABLE consent_event (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK (type IN ('health','ai_coach')), action TEXT NOT NULL CHECK (action IN ('grant','withdraw')), text_version TEXT NOT NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL) STRICT;
CREATE TABLE engine_decision (id TEXT PRIMARY KEY REFERENCES performed_exercise(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, instance_id TEXT, slot_id TEXT, exercise_id TEXT NOT NULL, result TEXT NOT NULL CHECK (result IN ('PROGRESS','HOLD','FAIL','IGNORED','DELOAD','ADJUSTED_HOLD','ADJUSTED_LIGHTEN','CALIBRATION','STALL')), reason_code TEXT NOT NULL, next_target TEXT CHECK (json_valid(next_target)), profile TEXT NOT NULL CHECK (profile IN ('adult','cautious')), rules_version TEXT NOT NULL) STRICT;
CREATE TABLE exercise (id TEXT PRIMARY KEY, schema_version INTEGER NOT NULL, revision INTEGER NOT NULL CHECK (revision >= 1), status TEXT NOT NULL CHECK (status IN ('draft','reviewed','published','retired')), batch TEXT NOT NULL CHECK (batch = 'A' OR batch = 'B' OR batch GLOB 'E[1-9]' OR batch GLOB 'E[1-9][0-9]'), name TEXT NOT NULL CHECK (length(name) <= 60), aliases TEXT CHECK (json_valid(aliases)), movement_pattern TEXT NOT NULL, mechanics TEXT NOT NULL CHECK (mechanics IN ('compound','isolation')), unilateral INTEGER NOT NULL CHECK (unilateral IN (0,1)), measure TEXT NOT NULL CHECK (measure IN ('reps','duration')), load_mode TEXT NOT NULL CHECK (load_mode IN ('barbell','dumbbell','machine','weighted','bodyweight','band')), level INTEGER NOT NULL CHECK (level IN (1,2,3)), not_for_minors INTEGER NOT NULL CHECK (not_for_minors IN (0,1)), primary_muscles TEXT CHECK (json_valid(primary_muscles)), secondary_muscles TEXT CHECK (json_valid(secondary_muscles)), equipment_options TEXT NOT NULL CHECK (json_valid(equipment_options)), stressed_joints TEXT CHECK (json_valid(stressed_joints)), content TEXT NOT NULL CHECK (json_valid(content)), chain_id TEXT, easier_id TEXT REFERENCES exercise(id) DEFERRABLE INITIALLY DEFERRED, harder_id TEXT REFERENCES exercise(id) DEFERRABLE INITIALLY DEFERRED, illustrations TEXT CHECK (json_valid(illustrations)), review_notes TEXT, drafting TEXT CHECK (json_valid(drafting)), reviewed_by TEXT REFERENCES user(id) ON DELETE SET NULL, reviewed_at TEXT, published_at TEXT, retired_at TEXT, updated_at TEXT, exported_revision INTEGER) STRICT;
CREATE TABLE exercise_comment (id TEXT PRIMARY KEY, exercise_id TEXT NOT NULL REFERENCES exercise(id), author_id TEXT REFERENCES user(id) ON DELETE SET NULL, part TEXT NOT NULL CHECK (part IN ('general','name','muscles','equipment','level','not_for_minors','stressed_joints','instructions','key_points','mistakes','safety','breathing','setup','variants','illustrations')), body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 1000), revision INTEGER NOT NULL CHECK (revision >= 1), created_at TEXT NOT NULL, resolved_at TEXT, resolved_by TEXT REFERENCES user(id) ON DELETE SET NULL, CHECK (resolved_at IS NOT NULL OR resolved_by IS NULL)) STRICT;
CREATE TABLE exercise_revision (exercise_id TEXT NOT NULL REFERENCES exercise(id), revision INTEGER NOT NULL CHECK (revision >= 1), content TEXT NOT NULL CHECK (json_valid(content)), status TEXT NOT NULL CHECK (status IN ('draft','reviewed','published','retired')), saved_by TEXT REFERENCES user(id) ON DELETE SET NULL, saved_at TEXT NOT NULL, PRIMARY KEY (exercise_id, revision)) STRICT;
CREATE TABLE exercise_validation (id TEXT PRIMARY KEY, exercise_id TEXT NOT NULL REFERENCES exercise(id), reviewer_id TEXT REFERENCES user(id) ON DELETE SET NULL, revision INTEGER NOT NULL CHECK (revision >= 1), health INTEGER NOT NULL CHECK (health IN (0,1)), created_at TEXT NOT NULL, UNIQUE (exercise_id, reviewer_id, revision)) STRICT;
CREATE TABLE gym (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 60), name_key TEXT NOT NULL, city TEXT NOT NULL CHECK (length(city) BETWEEN 2 AND 60), city_key TEXT NOT NULL, load_settings TEXT NOT NULL CHECK (json_valid(load_settings)), created_by TEXT REFERENCES user(id) ON DELETE SET NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE (name_key, city_key)) STRICT;
CREATE TABLE gym_equipment (id TEXT PRIMARY KEY, gym_id TEXT NOT NULL REFERENCES gym(id) ON DELETE CASCADE, equipment_code TEXT NOT NULL, added_by TEXT REFERENCES user(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, CHECK (id = gym_id || ':' || equipment_code)) STRICT;
CREATE TABLE gym_history (id TEXT PRIMARY KEY, gym_id TEXT NOT NULL REFERENCES gym(id) ON DELETE CASCADE, author_id TEXT REFERENCES user(id) ON DELETE SET NULL, at TEXT NOT NULL, action TEXT NOT NULL CHECK (action IN ('create','update_info','add_equipment','remove_equipment','update_load_settings')), detail TEXT NOT NULL CHECK (json_valid(detail))) STRICT;
CREATE TABLE health_screening (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, caution INTEGER CHECK (caution IN (0,1)), questionnaire_version TEXT, answered_at TEXT, CHECK (id = owner_id), CHECK (deleted_at IS NOT NULL OR (caution IS NOT NULL AND questionnaire_version IS NOT NULL AND answered_at IS NOT NULL))) STRICT;
CREATE TABLE home_equipment (id TEXT PRIMARY KEY, place_id TEXT NOT NULL REFERENCES place(id) ON DELETE CASCADE, equipment_code TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, CHECK (id = place_id || ':' || equipment_code)) STRICT;
CREATE TABLE illustration (id TEXT PRIMARY KEY, file TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL, media_type TEXT NOT NULL CHECK (media_type IN ('image/svg+xml','image/png','image/webp','image/jpeg')), source TEXT NOT NULL CHECK (source IN ('everkinetic','workout_guide')), source_url TEXT NOT NULL, creators TEXT NOT NULL CHECK (json_valid(creators)), license TEXT NOT NULL CHECK (license IN ('CC-BY-SA-4.0','CC-BY-4.0','CC0-1.0')), license_url TEXT NOT NULL, modifications TEXT, replace_before_public INTEGER NOT NULL DEFAULT 0 CHECK (replace_before_public IN (0,1))) STRICT;
CREATE TABLE instance_change (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, instance_id TEXT NOT NULL REFERENCES program_instance(id) ON DELETE CASCADE, base_revision INTEGER NOT NULL CHECK (base_revision >= 0), author TEXT NOT NULL CHECK (author IN ('user','coach','engine')), operations TEXT NOT NULL CHECK (json_valid(operations)), reason_code TEXT NOT NULL, reason TEXT, status TEXT NOT NULL CHECK (status IN ('proposed','accepted','rejected','expired')), expires_at TEXT, decided_at TEXT, ai_generated INTEGER NOT NULL DEFAULT 0 CHECK (ai_generated IN (0,1)), ai_model TEXT, prompt_version TEXT, coach_thread_id TEXT, CHECK (json_array_length(operations) BETWEEN 1 AND 5)) STRICT;
CREATE TABLE invitation (id TEXT PRIMARY KEY, code_hash TEXT NOT NULL UNIQUE, note TEXT CHECK (length(note) <= 60), birth_date TEXT, is_admin_bootstrap INTEGER NOT NULL DEFAULT 0 CHECK (is_admin_bootstrap IN (0,1)), created_by TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, used_by TEXT REFERENCES user(id) ON DELETE SET NULL, revoked_at TEXT) STRICT;
CREATE TABLE limitation (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, body_area TEXT CHECK (body_area IN ('shoulder','elbow','wrist_hand','neck','upper_back','lower_back','hip','knee','ankle_foot','other')), side TEXT CHECK (side IN ('left','right','both','not_applicable')), severity TEXT CHECK (severity IN ('mild','severe')), note TEXT CHECK (length(note) <= 200), active INTEGER CHECK (active IN (0,1)), CHECK (deleted_at IS NOT NULL OR (body_area IS NOT NULL AND side IS NOT NULL AND severity IS NOT NULL AND active IS NOT NULL))) STRICT;
CREATE TABLE nutrition_checkin (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, week_start TEXT, weigh_in_count INTEGER, mean_weight_g INTEGER, change_pct REAL, representative INTEGER CHECK (representative IN (0,1)), decision TEXT CHECK (decision IN ('insufficient_data','non_representative_week','in_band','out_of_band_pending','proposal','rapid_loss','limit_reached','safety_pause')), position TEXT CHECK (position IN ('above','in','below')), proposed_delta_kcal INTEGER CHECK (proposed_delta_kcal IN (-100,100)), response TEXT CHECK (response IN ('accepted','declined')), responded_at TEXT, created_target_id TEXT REFERENCES nutrition_target(id), recalibration_target_id TEXT REFERENCES nutrition_target(id), UNIQUE (owner_id, week_start), CHECK (deleted_at IS NOT NULL OR (week_start IS NOT NULL AND weigh_in_count IS NOT NULL AND representative IS NOT NULL AND decision IS NOT NULL))) STRICT;
CREATE TABLE nutrition_profile (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, mode TEXT NOT NULL DEFAULT 'disabled' CHECK (mode IN ('full','qualitative','disabled')), mode_reason TEXT CHECK (mode_reason IN ('choice','safety')), safety_screen_version INTEGER, safety_screen_at TEXT, safety_pause INTEGER NOT NULL DEFAULT 0 CHECK (safety_pause IN (0,1)), sex_for_calc TEXT CHECK (sex_for_calc IN ('male','female','unspecified')), height_cm INTEGER CHECK (height_cm BETWEEN 120 AND 220), activity_level INTEGER CHECK (activity_level BETWEEN 1 AND 4), goal TEXT CHECK (goal IN ('lose','maintain','gain')), cumulative_adjustment_kcal INTEGER NOT NULL DEFAULT 0 CHECK (cumulative_adjustment_kcal % 100 = 0), CHECK (id = owner_id)) STRICT;
CREATE TABLE nutrition_state (id INTEGER PRIMARY KEY CHECK (id = 1), full_open INTEGER NOT NULL DEFAULT 0 CHECK (full_open IN (0,1)), updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL) STRICT;
CREATE TABLE nutrition_target (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, valid_from TEXT, algo_version TEXT, reason TEXT CHECK (reason IN ('initial','checkin','weight_recalibration','profile_change','low_bmi_safety','new_algo_version')), inputs TEXT CHECK (json_valid(inputs)), effective_goal TEXT CHECK (effective_goal IN ('lose','maintain','gain')), bmr_kcal REAL, tdee_kcal REAL, kcal_target INTEGER, kcal_min INTEGER, kcal_max INTEGER, protein_g_min INTEGER, protein_g_max INTEGER, fat_g_min INTEGER, carbs_g INTEGER, fiber_g INTEGER, water_ml INTEGER, applied_rules TEXT CHECK (json_valid(applied_rules)), CHECK (deleted_at IS NOT NULL OR (valid_from IS NOT NULL AND algo_version IS NOT NULL AND reason IS NOT NULL AND inputs IS NOT NULL AND effective_goal IS NOT NULL AND bmr_kcal IS NOT NULL AND tdee_kcal IS NOT NULL AND kcal_target IS NOT NULL AND kcal_min IS NOT NULL AND kcal_max IS NOT NULL AND protein_g_min IS NOT NULL AND protein_g_max IS NOT NULL AND fat_g_min IS NOT NULL AND carbs_g IS NOT NULL AND fiber_g IS NOT NULL AND water_ml IS NOT NULL AND applied_rules IS NOT NULL))) STRICT;
CREATE TABLE password_reset (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, code_hash TEXT NOT NULL UNIQUE, created_by TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, cancelled_at TEXT) STRICT;
CREATE TABLE performed_exercise (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, session_id TEXT NOT NULL REFERENCES workout_session(id) ON DELETE CASCADE, slot_id TEXT, planned_exercise_id TEXT, exercise_id TEXT NOT NULL, swap_reason TEXT CHECK (swap_reason IN ('equipment','busy','pain','preference')), position INTEGER NOT NULL CHECK (position BETWEEN 1 AND 99), pain_level TEXT CHECK (pain_level IN ('none','discomfort','pain')), next_adjustment TEXT CHECK (next_adjustment IN ('hold','lighten')), note TEXT CHECK (length(note) <= 500)) STRICT;
CREATE TABLE performed_set (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, performed_exercise_id TEXT NOT NULL REFERENCES performed_exercise(id) ON DELETE CASCADE, position INTEGER NOT NULL CHECK (position BETWEEN 1 AND 99), kind TEXT NOT NULL CHECK (kind IN ('warmup','work')), load_mode TEXT NOT NULL CHECK (load_mode IN ('barbell','dumbbell','machine','weighted','bodyweight','band')), load_g INTEGER CHECK (load_g BETWEEN 0 AND 500000), reps INTEGER CHECK (reps BETWEEN 0 AND 200), duration_s INTEGER CHECK (duration_s BETWEEN 0 AND 7200), side TEXT CHECK (side IN ('left','right')), effort TEXT CHECK (effort IN ('easy','ok','hard','failed')), target_reps_min INTEGER, target_reps_max INTEGER, target_duration_s INTEGER, target_load_g INTEGER, target_rir INTEGER, target_variant TEXT, logged_at TEXT, target_reps INTEGER, CHECK (reps IS NULL OR duration_s IS NULL)) STRICT;
CREATE TABLE place (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, kind TEXT NOT NULL CHECK (kind IN ('gym','home')), gym_id TEXT REFERENCES gym(id), name TEXT CHECK (length(name) <= 30), is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)), visible_at_gym INTEGER NOT NULL DEFAULT 0 CHECK (visible_at_gym IN (0,1)), load_settings TEXT CHECK (json_valid(load_settings)), CHECK (kind = 'home' OR load_settings IS NULL), CHECK ((kind = 'gym') = (gym_id IS NOT NULL)), CHECK (kind = 'home' OR name IS NULL)) STRICT;
CREATE TABLE program_instance (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, template_id TEXT NOT NULL, template_version INTEGER NOT NULL, snapshot TEXT NOT NULL CHECK (json_valid(snapshot)), days_per_week INTEGER NOT NULL CHECK (days_per_week BETWEEN 2 AND 4), status TEXT NOT NULL CHECK (status IN ('active','ended')), revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0), started_at TEXT NOT NULL, ended_at TEXT) STRICT;
CREATE TABLE schema_migrations (id TEXT PRIMARY KEY, breaking INTEGER NOT NULL CHECK (breaking IN (0,1)), applied_at TEXT NOT NULL) STRICT;
CREATE TABLE security_event (id TEXT PRIMARY KEY, at TEXT NOT NULL, type TEXT NOT NULL, actor_id TEXT, target_id TEXT, tailnet_ip TEXT, outcome TEXT NOT NULL CHECK (outcome IN ('success','failure','blocked')), details TEXT CHECK (json_valid(details))) STRICT;
CREATE TABLE server_meta (id INTEGER PRIMARY KEY CHECK (id = 1), server_epoch TEXT NOT NULL, epoch_started_at TEXT NOT NULL, epoch_base_rev INTEGER NOT NULL DEFAULT 0, sync_counter INTEGER NOT NULL DEFAULT 0, tombstone_purge_rev INTEGER NOT NULL DEFAULT 0, catalog_version TEXT, catalog_updated_at TEXT) STRICT;
CREATE TABLE session (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, user_id TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, expires_at TEXT NOT NULL, must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0,1)), revoked_at TEXT, revoked_reason TEXT CHECK (revoked_reason IN ('logout','logout_all','password_change','password_reset','admin','account_deleted'))) STRICT;
CREATE TABLE slot_state (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, instance_id TEXT NOT NULL REFERENCES program_instance(id) ON DELETE CASCADE, slot_id TEXT NOT NULL, exercise_id TEXT NOT NULL, mode TEXT NOT NULL CHECK (mode IN ('linear','double','sum','chain','duration')), load_g INTEGER, target_reps INTEGER, variant_rank INTEGER, duration_s INTEGER, machine_step_g_override INTEGER, calibration_left INTEGER NOT NULL DEFAULT 0 CHECK (calibration_left >= 0), no_progress_count INTEGER NOT NULL DEFAULT 0 CHECK (no_progress_count >= 0), stall_rank INTEGER NOT NULL DEFAULT 0 CHECK (stall_rank >= 0), pain_streak INTEGER, suspended INTEGER NOT NULL DEFAULT 0 CHECK (suspended IN (0,1)), last_session_id TEXT, rules_version TEXT NOT NULL, CHECK (id = instance_id || ':' || slot_id || ':' || exercise_id)) STRICT;
CREATE TABLE sync_rejection (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, op_id TEXT NOT NULL, entity TEXT NOT NULL, row_id TEXT NOT NULL, code TEXT NOT NULL CHECK (code IN ('validation','forbidden','parent_rejected','stale_revision','unknown_entity','protocol','forbidden_reference','invalid_transition','unknown_exercise','out_of_range')), detail_json TEXT CHECK (json_valid(detail_json)), dismissed_at TEXT) STRICT;
CREATE TABLE training_profile (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, goal TEXT CHECK (goal IN ('muscle','strength','fat_loss','fitness','sport_support')), experience TEXT CHECK (experience IN ('none','lt_6_months','6_to_24_months','gt_24_months')), days_per_week INTEGER CHECK (days_per_week BETWEEN 2 AND 4), session_minutes INTEGER CHECK (session_minutes IN (30,45,60,75,90)), sport_code TEXT, sport_other_label TEXT CHECK (length(sport_other_label) <= 40), cautious_mode INTEGER NOT NULL DEFAULT 0 CHECK (cautious_mode IN (0,1)), coach TEXT CHECK (coach IN ('ombre','skald','scribe')), CHECK (id = owner_id)) STRICT;
CREATE TABLE user (id TEXT PRIMARY KEY, username TEXT NOT NULL, username_key TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','member')), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')), birth_date TEXT NOT NULL, terms_version TEXT, terms_accepted_at TEXT, last_login_at TEXT, password_changed_at TEXT, onboarding_step TEXT CHECK (onboarding_step IN ('goal','sport','place_kind','place','experience','availability','health','ready')), onboarding_completed_at TEXT, invitation_id TEXT REFERENCES invitation(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, catalog_reviewer INTEGER NOT NULL DEFAULT 0 CHECK (catalog_reviewer IN (0,1)), health_professional INTEGER NOT NULL DEFAULT 0 CHECK (health_professional IN (0,1))) STRICT;
CREATE TABLE weigh_in (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, date TEXT, weight_g INTEGER CHECK (weight_g BETWEEN 30000 AND 250000 AND weight_g % 100 = 0), CHECK (deleted_at IS NOT NULL OR (date IS NOT NULL AND weight_g IS NOT NULL))) STRICT;
CREATE TABLE workout_session (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, instance_id TEXT, workout_id TEXT, place_id TEXT, device_id TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL CHECK (status IN ('in_progress','completed','abandoned')), week_type TEXT NOT NULL CHECK (week_type IN ('normal','deload')), template_version INTEGER, rules_version TEXT NOT NULL, app_version TEXT NOT NULL, profile TEXT NOT NULL CHECK (profile IN ('adult','cautious')), note TEXT CHECK (length(note) <= 500)) STRICT;
CREATE INDEX applied_op_user_applied_idx ON applied_op (user_id, applied_at);
CREATE INDEX coach_call_created_idx ON coach_call (created_at);
CREATE INDEX coach_call_user_day_idx ON coach_call (user_id, day);
CREATE INDEX coach_thread_created_idx ON coach_thread (created_at);
CREATE INDEX coach_thread_last_message_idx ON coach_thread (last_message_at);
CREATE UNIQUE INDEX coach_thread_open_day_idx ON coach_thread (user_id, day) WHERE is_open = 1;
CREATE INDEX consent_event_owner_rev_idx ON consent_event (owner_id, rev);
CREATE INDEX consent_event_owner_type_created_idx ON consent_event (owner_id, type, created_at);
CREATE INDEX consent_event_rev_idx ON consent_event (rev);
CREATE INDEX engine_decision_owner_rev_idx ON engine_decision (owner_id, rev);
CREATE INDEX engine_decision_rev_idx ON engine_decision (rev);
CREATE INDEX exercise_chain_idx ON exercise (chain_id);
CREATE INDEX exercise_comment_author_idx ON exercise_comment (author_id);
CREATE INDEX exercise_comment_exercise_idx ON exercise_comment (exercise_id);
CREATE INDEX exercise_movement_pattern_idx ON exercise (movement_pattern);
CREATE INDEX exercise_status_idx ON exercise (status);
CREATE INDEX exercise_validation_reviewer_idx ON exercise_validation (reviewer_id);
CREATE INDEX gym_equipment_gym_idx ON gym_equipment (gym_id);
CREATE INDEX gym_equipment_rev_idx ON gym_equipment (rev);
CREATE INDEX gym_history_gym_at_idx ON gym_history (gym_id, at);
CREATE INDEX gym_rev_idx ON gym (rev);
CREATE INDEX health_screening_owner_rev_idx ON health_screening (owner_id, rev);
CREATE INDEX health_screening_rev_idx ON health_screening (rev);
CREATE INDEX home_equipment_owner_rev_idx ON home_equipment (owner_id, rev);
CREATE INDEX home_equipment_place_idx ON home_equipment (place_id);
CREATE INDEX home_equipment_rev_idx ON home_equipment (rev);
CREATE INDEX instance_change_instance_created_idx ON instance_change (instance_id, created_at);
CREATE INDEX instance_change_owner_rev_idx ON instance_change (owner_id, rev);
CREATE INDEX instance_change_owner_status_idx ON instance_change (owner_id, status);
CREATE INDEX instance_change_rev_idx ON instance_change (rev);
CREATE INDEX limitation_owner_rev_idx ON limitation (owner_id, rev);
CREATE INDEX limitation_rev_idx ON limitation (rev);
CREATE INDEX nutrition_checkin_owner_rev_idx ON nutrition_checkin (owner_id, rev);
CREATE INDEX nutrition_checkin_rev_idx ON nutrition_checkin (rev);
CREATE INDEX nutrition_profile_owner_rev_idx ON nutrition_profile (owner_id, rev);
